package in.agricred.farmerservice; import jakarta.persistence.*; import java.time.Instant; @Entity @Table(name="farmer_profiles") public class FarmerProfile { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id; @Column(nullable=false,unique=true) public String email; public String fullName; public String phone; public String district; public String state; public Double landAcres; public String landOwnership; public String primaryCrop; public String cropSeason; public Double expectedYieldQuintals; public Double expectedIncome; public Double annualIncome; public Double existingDebt; public Integer latePayments; public Integer onTimePayments; public String landDocumentName; public String landDocumentPath; public Instant updatedAt=Instant.now(); public FarmerProfile(){} }